{
  "name": "clearance",
  "version": "0.1.1",
  "description": "Machine-wide resource clearance for Claude Code sessions and subagents: see the headroom, and get cleared, held or diverted before launching more.",
  "author": {
    "name": "wombraider"
  },
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "minFreeGB": {
      "type": "number",
      "title": "Available memory floor (GB)",
      "description": "Available RAM (free plus standby) that must remain after admitting a session or subagent. 0 means learned: where this machine was seen to start paging hard, and 5% of RAM until it has been. A positive value fixes it.",
      "default": 0
    },
    "maxCommitPct": {
      "type": "number",
      "title": "Commit ceiling (%)",
      "description": "Committed memory as a share of the commit limit, after admitting.",
      "default": 90
    },
    "maxSessions": {
      "type": "number",
      "title": "Session ceiling",
      "description": "Most local Claude sessions at once.",
      "default": 6
    },
    "maxAgents": {
      "type": "number",
      "title": "Subagent ceiling",
      "description": "Most subagents in flight across the machine.",
      "default": 8
    },
    "sessionBaselineGB": {
      "type": "number",
      "title": "New session cost (GB)",
      "description": "0 means learned: an upper bound on what this machine's sessions were seen to grow to. A positive value fixes it.",
      "default": 0
    }
  }
}

files.types/index.d.ts:
/** The gate view's HOLD reasons (the badge and the pane show them); null while cleared. */
export type ClearanceBand = { state: 'HOLD'; headroomMB: number; reasons: string[] }

/** One session in the chip's hover card. */
export type ClearanceBadgeRow = {
  /** The session's folder, last segment. */
  where: string
  selfMB: number
  childMB: number
  /** Subagents in flight; null for a session without the mod. */
  agents: number | null
  isSelf: boolean
  /** Its attributed containers' memory. */
  containersMB: number
}

/** The band's badge, always up: the marshaller's mood and the line beside it. */
export type ClearanceBadge = {
  mood: 'CLEARED' | 'HOLD' | 'THRASH' | 'WAITING'
  /** Rounded to 0.1 GB; null while WAITING. */
  headroomMB: number | null
  /** More sessions that fit now. */
  fits: number
  /** More general-purpose subagents that fit now (their forecast is smaller than a session's). */
  agentFits: number
  /** RAM in use, percent of total, and what is available (free plus standby); 0 while WAITING. */
  usedPct: number
  availableMB: number
  totalMB: number
  sessions: number
  agents: number
  /** Why it holds; empty unless HOLD. */
  reasons: string[]
  /** Why there are no numbers while WAITING; empty otherwise. */
  note: string
  /** The gate's numbers, so the chip can say why it holds. */
  floorMB: number
  agentAskMB: number
  sessionAskMB: number
  /** What the subagent ask rests on (a bound over runs, the largest seen, or the stand-in). */
  agentBasis: string
  /** Every session's use, largest first, for the hover card. */
  rows: ClearanceBadgeRow[]
  /** RAM in use that no session owns: the desktop app, WSL, browsers, the rest of the machine. */
  otherMB: number
  /** RAM in use, percent, over the last samples, oldest first: the band's sparkline. */
  ramTrail: number[]
  /** Hard page reads per second in the latest sample; null when the sampler doesn't read it. */
  pagesInPerSec: number | null
  /** What the floor rests on (learned from paging, or the policy). */
  floorBasis: string
  /** The desktop app, the WSL/Docker VM and the containers no session owns, MB. */
  desktopMB: number
  dockerVmMB: number
  unattributedContainersMB: number
}

/** One session row of the /clearance pane. */
export type ClearancePaneSession = {
  id: string
  /** The session's folder, last two segments. */
  where: string
  selfMB: number
  childMB: number
  children: number
  /** Subagents in flight; null for a session without the mod. */
  agents: number | null
  /** Seconds since the session last made progress; null without the mod. */
  progressAgoS: number | null
  /** Its largest child process, `name size`. */
  top: string
  isSelf: boolean
}

/** What the /clearance pane draws, rebuilt every sample. */
export type ClearancePane = {
  t: number
  epoch: number
  isScribe: boolean
  state: 'CLEARED' | 'HOLD' | 'THRASH'
  headroomMB: number
  fits: number
  reasons: string[]
  machine: { totalMB: number; availableMB: number; commitMB: number; commitLimitMB: number }
  /** `minFreeGB` is the floor in effect (the auto floor resolved). */
  limits: { minFreeGB: number; maxCommitPct: number; maxSessions: number; maxAgents: number }
  agents: number
  reservedMB: number
  sessions: ClearancePaneSession[]
  /** Memory no session owns, and what the floor rests on: one line each. */
  others: string[]
}

declare module 'claude-code' {
  interface PluginState {
    clearance: {
      badge: ClearanceBadge | null
      pane: ClearancePane | null
      /** The session-start check ran (once per session, not again on a hot reload). */
      startChecked: boolean
      /** The person chose to wait at the session-start dialog: toast once the machine clears. */
      waitingForClearance: boolean
    }
  }
}
